const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/financial_periods',
  qs: {
    'filters[from_date]': '2026-01-01',
    'filters[to_date]': '2026-12-31',
    sort: '-date',
    page: '1',
    per_page: '10'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/financial_periods?filters%5Bfrom_date%5D=2026-01-01&filters%5Bto_date%5D=2026-12-31&sort=-date&page=1&per_page=10"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

